public partial class PositionConnectorReference{Logger m_log=new();Dictionary<string,AgentPosition> m_updateAgentQueue=new();ExpiringCache<string,bool> _failedSims=new();int paths,throwPath;bool custom;string AgentPath(){if(++paths==throwPath)throw new Exception();return custom?"custom/":"agent/";}void StopTimer(){((System.Timers.Timer)typeof(ExpiringCache<string,bool>).GetField("timer",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(_failedSims)).Stop();}void Advance(double seconds){var storage=(IDictionary)typeof(ExpiringCache<string,bool>).GetField("timedStorage",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(_failedSims);foreach(var key in storage.Keys){var f=key.GetType().GetField("expirationDate",BindingFlags.NonPublic|BindingFlags.Instance);f.SetValue(key,((DateTime)f.GetValue(key)).AddSeconds(-seconds));}}void Purge()=>typeof(ExpiringCache<string,bool>).GetMethod("PurgeCache",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(_failedSims,new object[]{null,null});static UUID Id(int n)=>new UUID("00000000-0000-0000-0000-00000000000"+n);static GridRegion Region(bool second=false)=>new(){RegionID=Id(second?8:9),RegionLocX=25600,RegionLocY=51200,RegionName="Destination",ServerURI=second?"http://other:9000/base/":"http://sim:9000/base/"};static AgentPosition Position(float far=10,int agent=7)=>new(){AgentID=Id(agent),Position=new(1.25f,2,30),Far=far};static string H(string s)=>Convert.ToHexString(Encoding.UTF8.GetBytes(s)).ToLowerInvariant();static string Status(Func<bool> call){try{return call()?"1":"0";}catch{return "EX";}}
static void Main(){Culture.SetCurrentCulture();string line;while((line=Console.ReadLine())!=null){var args=(OSDMap)OSDParser.DeserializeJson(Encoding.UTF8.GetString(Convert.FromHexString(line)));string mode=args["mode"].AsString(),trace="",nested="",results="";int calls=0;var first=Position();if(args["bad_pack"].AsBoolean())first.GodData=new OSD();var second=Position(20);var third=Position(30);var a=Region();var b=Region(true);var handler=new PositionConnectorReference{throwPath=args["throw_path"].AsInteger(),custom=args["custom"].AsBoolean()};handler.StopTimer();var entered=new ManualResetEventSlim();var proceed=new ManualResetEventSlim();WebUtil.Request=(uri,data,timeout,compressed)=>{++calls;trace+=H(uri)+":"+timeout+":"+(compressed?1:0)+":"+H(OSDParser.SerializeJsonString(data,true))+";";if(calls==1){if(mode=="parallel"){entered.Set();proceed.Wait();}else if(mode=="coalesce"||mode=="failure_queued"){nested+=Status(()=>handler.UpdateAgent(a,second))+",";nested+=Status(()=>handler.UpdateAgent(a,third))+",";}else if(mode=="same"){first.Far=99;nested+=Status(()=>handler.UpdateAgent(a,first))+",";}}var replies=(OSDArray)args["replies"];var reply=replies[Math.Min(calls-1,replies.Count-1)];if(reply.Type==OSDType.String&&reply.AsString()=="throw")throw new Exception();return reply.Type==OSDType.Unknown?null:(OSDMap)reply;};Func<GridRegion,AgentPosition,string> call=(d,p)=>Status(()=>handler.UpdateAgent(d,p));Action<string> append=s=>results+=s+",";
if(mode=="worker"){var context=new EntityTransferContext{OutboundVersion=(float)args["version"].AsReal()};append(Status(()=>handler.UpdateAgent(args["null_destination"].AsBoolean()?null:a,(IAgentData)(args["null_data"].AsBoolean()?null:first),args["null_context"].AsBoolean()?null:context,args["timeout"].AsInteger())));}else if(mode=="parallel"){var worker=Task.Run(()=>call(a,first));if(!entered.Wait(5000))throw new Exception("request barrier");nested+=call(a,second)+",";nested+=call(a,third)+",";proceed.Set();append(worker.GetAwaiter().GetResult());}else{append(call(args["null_destination"].AsBoolean()?null:a,args["null_data"].AsBoolean()?null:first));if(mode=="repeat"||mode=="failure_queued")append(call(a,first));else if(mode=="other_agent"){append(call(a,Position(40,8)));append(call(b,first));}else if(mode=="cooldown"){handler.Advance(130);append(call(a,first));handler.Purge();append(call(a,first));}else if(mode=="clock_back"){handler.Advance(-130);handler.Purge();append(call(a,first));handler.Advance(260);handler.Purge();append(call(a,first));}else if(mode=="purge_order"){handler.Advance(-100);append(call(b,first));handler.Advance(130);handler.Purge();append(call(b,first));handler.Advance(100);handler.Purge();append(call(b,first));}}Console.WriteLine(results+"|"+nested+"|"+H(trace)+"|"+handler._failedSims.Count+"|"+handler.paths);}}}
